// A measured overlay gives textarea cursors a consistent three-pixel width.
const thickSqlCaret=document.createElement('span');
thickSqlCaret.className='thick-sql-caret';
thickSqlCaret.setAttribute('aria-hidden','true');
const sqlCaretMirror=document.createElement('div');
sqlCaretMirror.className='sql-caret-mirror';
let sqlCaretFrame=0;
function updateThickSqlCaret(){
 sqlCaretFrame=0;
 const host=document.fullscreenElement||document.body;
 if(thickSqlCaret.parentNode!==host)host.append(thickSqlCaret,sqlCaretMirror);
 const input=document.activeElement;
 document.querySelectorAll('.sql-thick-caret-active').forEach(element=>element.classList.remove('sql-thick-caret-active'));
 thickSqlCaret.hidden=true;
 if(!input?.matches('#editor,#cliInput')||input.disabled||input.selectionStart!==input.selectionEnd)return;
 const rect=input.getBoundingClientRect(),style=getComputedStyle(input);
 if(!rect.width||!rect.height)return;
 for(const property of ['fontFamily','fontSize','fontWeight','fontStyle','lineHeight','letterSpacing','tabSize','paddingTop','paddingRight','paddingBottom','paddingLeft','borderTopWidth','borderRightWidth','borderBottomWidth','borderLeftWidth','boxSizing','textIndent','textTransform','wordSpacing'])sqlCaretMirror.style[property]=style[property];
 sqlCaretMirror.style.width=rect.width+'px';
 sqlCaretMirror.style.whiteSpace=style.whiteSpace;
 sqlCaretMirror.style.overflowWrap=style.overflowWrap;
 sqlCaretMirror.style.wordBreak=style.wordBreak;
 sqlCaretMirror.replaceChildren(document.createTextNode(input.value.slice(0,input.selectionStart)));
 const marker=document.createElement('span');marker.textContent='\u200b';sqlCaretMirror.append(marker);
 const mirrorRect=sqlCaretMirror.getBoundingClientRect(),markerRect=marker.getBoundingClientRect();
 const x=rect.left+markerRect.left-mirrorRect.left-input.scrollLeft;
 const y=rect.top+markerRect.top-mirrorRect.top-input.scrollTop;
 const lineHeight=parseFloat(style.lineHeight)||parseFloat(style.fontSize)*1.6;
 if(x<rect.left||x>rect.right-2||y<rect.top||y+lineHeight>rect.bottom+1)return;
 thickSqlCaret.style.left=x+'px';thickSqlCaret.style.top=y+'px';
 thickSqlCaret.style.height=lineHeight+'px';thickSqlCaret.hidden=false;input.classList.add('sql-thick-caret-active');
}
function scheduleThickSqlCaret(){if(!sqlCaretFrame)sqlCaretFrame=requestAnimationFrame(updateThickSqlCaret)}
for(const type of ['input','keyup','pointerup','focusin','focusout','selectionchange','scroll','fullscreenchange'])document.addEventListener(type,scheduleThickSqlCaret,true);
window.addEventListener('resize',scheduleThickSqlCaret);
scheduleThickSqlCaret();

